		addRel := func(n, rel string) {
			if n != "" && n != "null" {
				p := strings.Fields(n)
				if len(p) > 0 {
					relatives = append(relatives, Relative{
						FirstName:    p[0],
						LastName:     p[len(p)-1],
						Relationship: rel,
					})
				}
			}
		}

		addRel(father, "Father")
		addRel(mother, "Mother")
		addRel(brother, "Brother")
		addRel(sister, "Sister")

		people = append(people, Person{
			FirstName: fName,
			LastName:  lName,
			Birthday:  birthdayFormatted,
			Age:       age,
			Relatives: relatives,
		})
